### Part 1: Project Setup

First, create a root folder for your project and set up the directory structure.

```bash
mkdir my-app
cd my-app
mkdir server client
```

---

### Part 2: Backend (Node + Express)

We will build a simple API to manage "Dummy Data" (e.g., a list of users).

#### 1. Initialize Backend
```bash
cd server
npm init -y
npm install express cors nodemon
npm install --save-dev nodemon
```

#### 2. Create Server Logic
Create a file named `index.js` inside the `server` folder.

**File: `server/index.js`**
```javascript
const express = require('express');
const cors = require('cors');

const app = express();
const PORT = 5000;

// Middleware
app.use(cors()); // Allows React to talk to Node
app.use(express.json()); // Allows parsing JSON bodies

// --- IN-MEMORY DATABASE (Dummy Data) ---
// In a real app, use MongoDB, SQL, etc.
let dummyData = [
    { id: 1, name: 'Alice', role: 'Admin' },
    { id: 2, name: 'Bob', role: 'User' }
];

// --- API ROUTES ---

// 1. GET: Fetch all data
app.get('/api/users', (req, res) => {
    res.json(dummyData);
});

// 2. POST: Add new data
app.post('/api/users', (req, res) => {
    const { name, role } = req.body;
    if (!name) return res.status(400).json({ msg: 'Name is required' });

    const newUser = { id: Date.now(), name, role: role || 'User' };
    dummyData.push(newUser);
    res.status(201).json(newUser);
});

// 3. DELETE: Remove data
app.delete('/api/users/:id', (req, res) => {
    const id = parseInt(req.params.id);
    dummyData = dummyData.filter(user => user.id !== id);
    res.json({ msg: 'Deleted', users: dummyData });
});

// Start Server
app.listen(PORT, () => console.log(`Server running on port ${PORT}`));
```

#### 3. Update `package.json` Scripts
Add this to `server/package.json` to run easily:
```json
"scripts": {
  "start": "node index.js",
  "dev": "nodemon index.js"
}
```

