public int longestSubArray(int[] a, int k) {
    if (a == null || a.length == 0) return 0;
    int start = 0;
    int end = 0;
    int max = Integer.MIN_VALUE;
    int currentSum = a[0];
    for (end = 1; end < a.length; end++) {
        currentSum += a[end];
        if (currentSum > k) {
            while (currentSum > k) {
                currentSum -= a[start];
                start++;
            }
        }
        if (currentSum <= k) {
            if (end - start + 1 > max) {
                max = end - start + 1;
            }
        }
    }
    return max;
}

